package com.mcnex.conversation;
import android.app.*;import android.os.*;import android.content.*;import org.json.*;import java.io.*;import java.util.concurrent.atomic.AtomicBoolean;
public class ModelLoadProbe extends Instrumentation {
 JSONObject report=new JSONObject();JSONArray rows=new JSONArray();
 public void onCreate(Bundle b){super.onCreate(b);start();}
 JSONObject battery()throws Exception{Intent i=getTargetContext().registerReceiver(null,new IntentFilter(Intent.ACTION_BATTERY_CHANGED));return new JSONObject().put("temperatureC",i.getIntExtra(BatteryManager.EXTRA_TEMPERATURE,0)/10.0).put("plugged",i.getIntExtra(BatteryManager.EXTRA_PLUGGED,0)).put("thermalStatus",getTargetContext().getSystemService(PowerManager.class).getCurrentThermalStatus());}
 void save()throws Exception{report.put("rows",rows);try(FileOutputStream f=getTargetContext().openFileOutput("model-resource-probe.json",0)){f.write(report.toString().getBytes("UTF-8"));}}
 public void onStart(){try{String[] names={"Qwen3-0.6B LiteRT GPU","Gemma E2B LiteRT GPU","EXAONE 2.4B OpenCL GPU"};File dir=getTargetContext().getFilesDir();report.put("cores",Runtime.getRuntime().availableProcessors());for(int model=0;model<3;model++){Bundle stage=new Bundle();stage.putString("model",names[model]);sendStatus(1,stage);JSONObject row=new JSONObject().put("model",names[model]).put("before",battery()).put("baselinePssKb",Debug.getPss());long begin=SystemClock.elapsedRealtime();AiEngine engine=model==2?new LocalAi(new File(dir,"model.gguf"),true):new LiteAi(new File(dir,model==0?"model.litertlm":"gemma-resource-test.litertlm"),getTargetContext().getCacheDir());row.put("loadMs",SystemClock.elapsedRealtime()-begin).put("loadedPssKb",Debug.getPss());AtomicBoolean sampling=new AtomicBoolean(true);long[] peak={Debug.getPss()};Thread monitor=new Thread(()->{while(sampling.get()){peak[0]=Math.max(peak[0],Debug.getPss());try{Thread.sleep(500);}catch(Exception ignored){}}});monitor.start();long wall=SystemClock.elapsedRealtime(),cpu=android.os.Process.getElapsedCpuTime();JSONArray samples=new JSONArray();try{for(int i=0;i<3;i++){long t=SystemClock.elapsedRealtime();String answer=engine.explain("역광에서 사람 얼굴이 어둡게 나오는 카메라 문제를 검토합니다. HDR을 적용하면 밝은 배경과 얼굴을 함께 개선할 수 있을까요?","자동 대화 도움","assist");samples.put(new JSONObject().put("elapsedMs",SystemClock.elapsedRealtime()-t).put("characters",answer.length()));}}finally{long elapsed=SystemClock.elapsedRealtime()-wall,used=android.os.Process.getElapsedCpuTime()-cpu;sampling.set(false);monitor.join(1500);row.put("generateWallMs",elapsed).put("processCpuMs",used).put("singleCoreCpuPercent",100.0*used/Math.max(1,elapsed)).put("peakPssKb",peak[0]).put("samples",samples).put("after",battery());engine.close();rows.put(row);save();}}report.put("ok",true);save();}catch(Exception|LinkageError e){try{report.put("ok",false).put("error",e.toString());save();}catch(Exception ignored){}}Bundle out=new Bundle();out.putString("file","model-resource-probe.json");finish(report.optBoolean("ok")?-1:0,out);}
}
